#!/usr/bin/env bash
# check-scale.sh — what a program of many bundles and many shards costs, compiled (docs/PERF.md).
#
#   bash tools/check-scale.sh                 # the standard sizes
#   bash tools/check-scale.sh 100x100:messages 50x20:ticks     # chosen ones
#   THREADS=4 bash tools/check-scale.sh       # (from P4) the same, on four threads
#
# Each size is generated by tools/gen-scale.sh, emitted to C#, built in Release and run twice — SHORT and LONG
# frames — and the difference is divided by the frames between: process start, building the world and JIT
# warm-up cancel out, as in check-perf.sh. Best of REPEATS. Also: how long the C# takes to build, and the
# checksum the program prints at frame 10 (the same on any runtime and any thread count — the proof that a
# faster run is the same run).
set -u

REPO="$(cd "$(dirname "$0")/.." && pwd)"
WIN_REPO="$(cd "$REPO" && pwd -W 2>/dev/null || echo "$REPO")"
WORK="${TMPDIR:-/tmp}/vein-scale-check"
CLI="${VEINC_RELEASE:-$WORK/cli/veinc.dll}"
# PAST WARM-UP. A program of 10,000 shards is 10,000 handler methods, each JIT-compiled and then re-optimised
# after ~30 calls: frames 20..120 of the 100x100 messages program cost 52 ms each, frames 200..600 cost 30.
# A window that starts early measures the JIT, not the program.
SHORT="${SHORT:-200}"
LONG="${LONG:-600}"
REPEATS="${REPEATS:-2}"
SIZES=("$@")
[ ${#SIZES[@]} -eq 0 ] && SIZES=(10x10:messages 100x10:messages 100x100:messages 100x100:ticks 100x100:mixed)

mkdir -p "$WORK"
if [ -z "${VEINC_RELEASE:-}" ]; then
    echo "building veinc (Release)…"
    dotnet build "$REPO/src/Vein.Cli" -c Release -o "$WORK/cli" -v quiet -nologo >/dev/null 2>&1 || { echo "BUILD FAILED"; exit 1; }
fi

ms() { echo $(( $(date +%s%N) / 1000000 )); }

best() {   # best wall time (ms) of REPEATS runs of: dll ticks
    local dll="$1" ticks="$2" best=999999999 t0 t
    for ((r = 0; r < REPEATS; r++)); do
        t0=$(ms); dotnet "$dll" --ticks "$ticks" ${THREADS:+--threads "$THREADS"} >/dev/null 2>&1; t=$(( $(ms) - t0 ))
        (( t < best )) && best=$t
    done
    echo "$best"
}

printf "%-18s %8s %10s %12s %14s %s\n" size shards build_s frame_ms per_second checksum
for size in "${SIZES[@]}"; do
    dims="${size%%:*}"; work="${size##*:}"; n="${dims%%x*}"; m="${dims##*x}"
    dir="$WORK/$n-$m-$work"; out="$dir/gen"
    bash "$REPO/tools/gen-scale.sh" "$dir" "$n" "$m" "$work" >/dev/null
    mkdir -p "$out"

    t0=$(ms)
    dotnet "$CLI" emit "$dir/main.vein" -o "$out" >/dev/null 2>&1 || { echo "$size: emit failed"; continue; }
    cat > "$out/gen.csproj" <<XML
<Project Sdk="Microsoft.NET.Sdk">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>disable</Nullable>
    <ImplicitUsings>enable</ImplicitUsings>
    <AssemblyName>scale_gen</AssemblyName>
    <Configuration>Release</Configuration>
  </PropertyGroup>
  <ItemGroup>
    <ProjectReference Include="$WIN_REPO/src/Vein.Runtime.SECS/Vein.Runtime.SECS.csproj" />
  </ItemGroup>
</Project>
XML
    dotnet build "$out/gen.csproj" -c Release -v quiet -nologo > "$out/build.log" 2>&1 || { echo "$size: the C# does not build (see $out/build.log)"; continue; }
    build=$(( $(ms) - t0 ))
    dll="$out/bin/Release/net8.0/scale_gen.dll"

    checksum=$(dotnet "$dll" --ticks 12 ${THREADS:+--threads "$THREADS"} 2>&1 | grep -o "checksum .*" | head -1)
    # Enough frames that the run, not the process start, is what is timed: grow until the long run takes 2 s.
    lo=$SHORT; hi=$LONG
    while (( $(best "$dll" "$hi") < 2000 && hi < 200000 )); do lo=$((lo * 4)); hi=$((hi * 4)); done
    short=$(best "$dll" "$lo"); long=$(best "$dll" "$hi")
    frame=$(awk -v s="$short" -v l="$long" -v f=$((hi - lo)) 'BEGIN { printf "%.3f", (l - s) / f }')
    case "$work" in
        messages) per=$(awk -v f="$frame" -v e=$((n * m)) 'BEGIN { printf "%.0f msg/s", (f > 0) ? e / f * 1000 : 0 }') ;;
        ticks)    per=$(awk -v f="$frame" -v e=$((n * m * 10)) 'BEGIN { printf "%.0f act/s", (f > 0) ? e / f * 1000 : 0 }') ;;
        mixed)    per=$(awk -v f="$frame" -v e=$((n * m * 11)) 'BEGIN { printf "%.0f units/s", (f > 0) ? e / f * 1000 : 0 }') ;;
    esac
    printf "%-18s %8s %10.1f %12s %14s %s\n" "$size" $((n * m)) "$(awk -v b="$build" 'BEGIN { print b / 1000 }')" "$frame" "$per" "${checksum:-(none)}"
done
